 const box=$('marketDecisionGrid');if(!box)return;const st=marketCandidateStats(valid),ctx=data?.market_context||{};
 const mk=(m)=>{const s=marketSession(m),flag=m==='US'?'🇺🇸':'🇰🇷',name=m==='US'?'미국':'한국',all=st.qualified.filter(x=>itemMarket(x)===m),allocated=all.filter(x=>Number(x.qty||0)>0),near=st.near.filter(x=>itemMarket(x)===m),openNow=allocated.filter(immediateAllowed).length,c=ctx[m]||{};const breadth=c.sample?`${escapeText(c.label||'')} ${Number(c.score||0).toFixed(0)}점 · 20일선 위 ${Number(c.above_ma20_pct||0).toFixed(0)}% · 5일 상승 ${Number(c.positive_5d_pct||0).toFixed(0)}%`:'시장 확산도 계산 중';return `<div class="market-decision ${s.open?'market-open':'market-closed'}"><div><b>${flag} ${name}</b><span>${escapeText(s.label)} · ${escapeText(s.local_time||'')}</span></div><strong>기준통과 ${all.length}개 · 실제배정 ${allocated.length}개${near.length?` · 근접 ${near.length}개`:''}</strong><small>${breadth}<br>${s.open?(openNow?`정규장 즉시 후보 ${openNow}개`:'정규장 중 · 배정 가능한 후보 없음'):s.extended_open?'연장거래는 관찰만 · 다음 정규장 재검증':'다음 정규장 재검증'}</small></div>`};
