function fmt(n){return Number(n||0).toLocaleString('ko-KR')}
function compact(n){if(n===null||n===undefined)return'-';const v=Number(n);if(!Number.isFinite(v))return'-';return new Intl.NumberFormat('ko-KR',{notation:'compact',maximumFractionDigits:1}).format(v)}
function pct(n){if(n===null||n===undefined)return'-';const v=Number(n);return`${v>=0?'+':''}${v.toFixed(2)}%`}
function escapeText(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function dateLabel(iso){try{return new Intl.DateTimeFormat('ko-KR',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(iso))}catch(e){return iso||'없음'}}
function loadJson(key,fallback){try{let raw=localStorage.getItem(key);if(!raw&&key===HISTORY_KEY)raw=localStorage.getItem('v78.1.0-recommendation-history')||localStorage.getItem('v70.15.0-recommendation-history')||localStorage.getItem('v70.14.2-recommendation-history')||localStorage.getItem('v70.14.1-recommendation-history');if(!raw&&key===RANK_KEY)raw=localStorage.getItem('v78.1.0-rank-baseline')||localStorage.getItem('v70.15.0-rank-baseline')||localStorage.getItem('v70.14.2-rank-baseline')||localStorage.getItem('v70.14.1-rank-baseline');const v=JSON.parse(raw||'null');return v??fallback}catch(e){return fallback}}
