function candidateRankList(results){const strict=sortedDefault((results||[]).filter(x=>x.category!=='ETF'&&candidateTier(x)==='buy'));const queue=sortedDefault((results||[]).filter(x=>x.category!=='ETF'&&candidateTier(x)==='queue'));const watch=sortedDefault((results||[]).filter(x=>x.category!=='ETF'&&candidateTier(x)==='watch'&&!strict.includes(x)));return [...strict,...queue,...watch].slice(0,10)}
function annotateRankChanges(data){const base=loadJson(RANK_KEY,{items:{}}),prev=base.items||{},list=candidateRankList(data.results||[]);list.forEach((x,i)=>{const rank=i+1,k=resultKey(x),old=prev[k];x.client_rank=rank;if(!old){x.rank_trend='🆕 신규 TOP10';x.top3_streak=rank<=3?1:0}else{const delta=Number(old.rank||0)-rank;x.rank_trend=delta>0?`▲ ${old.rank}→${rank}`:delta<0?`▼ ${old.rank}→${rank}`:'▬ 순위 유지';x.top3_streak=rank<=3?Number(old.top3_streak||0)+1:0}})}
function saveRankBaseline(data){const items={};candidateRankList(data.results||[]).forEach((x,i)=>{items[resultKey(x)]={rank:i+1,top3_streak:Number(x.top3_streak||0)}});saveJson(RANK_KEY,{generated_at:data.generated_at||new Date().toISOString(),items})}
function rankBadge(x){if(!x)return'';const streak=Number(x.top3_streak||0);return `${x.rank_trend||''}${streak>=2?` · 🔥 ${streak}회 연속 분석 TOP3`:''}`.trim()}
function localDayKey(iso){try{const d=new Date(iso);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}catch(e){return String(iso||'').slice(0,10)}}
function tradingDaysElapsed(startIso,endIso,market){try{const m=normalizeMarket(market),hol=m==='US'?US_HOLIDAYS:KR_HOLIDAYS;let d=new Date(startIso),end=new Date(endIso),count=0;d=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate()));const e=new Date(Date.UTC(end.getUTCFullYear(),end.getUTCMonth(),end.getUTCDate()));while(d<e&&count<370){d.setUTCDate(d.getUTCDate()+1);const wd=d.getUTCDay(),key=d.toISOString().slice(0,10);if(wd!==0&&wd!==6&&!hol.has(key))count++}return count}catch(e){return 0}}
function updateRecommendationHistory(data){const history=loadJson(HISTORY_KEY,[]),nowIso=data.generated_at||new Date().toISOString(),nowMs=new Date(nowIso).getTime();const current=new Map((data.results||[]).filter(x=>x.ok).map(x=>[resultKey(x),x]));
 history.forEach(r=>{const x=current.get(r.result_key);if(!x)return;const price=Number(x.price_krw||0);if(!price||!r.recommend_price)return;const ret=(price/r.recommend_price-1)*100;r.current_return=Number(ret.toFixed(2));r.last_seen_at=nowIso;r.observed_max_return=Math.max(Number(r.observed_max_return??ret),ret);r.observed_min_return=Math.min(Number(r.observed_min_return??ret),ret);const td=tradingDaysElapsed(r.created_at,nowIso,r.market||((r.result_key||'').startsWith('US:')?'US':'KR'));if(td>=1&&r.d1_return==null)r.d1_return=Number(ret.toFixed(2));if(td>=3&&r.d3_return==null)r.d3_return=Number(ret.toFixed(2));if(td>=5&&r.d5_return==null)r.d5_return=Number(ret.toFixed(2));if(td>=10&&r.d10_return==null)r.d10_return=Number(ret.toFixed(2));if(td>=20&&r.d20_return==null)r.d20_return=Number(ret.toFixed(2));if(price>=Number(r.target||Infinity))r.status='🎯 목표 관찰';else if(price<=Number(r.stop||-Infinity))r.status='🛑 손절선 관찰';else r.status='진행중'});
 const individual=sortedDefault((data.results||[]).filter(x=>x.ok&&x.category!=='ETF'&&candidateTier(x)==='buy'))[0];const etf=sortedDefault((data.results||[]).filter(x=>x.ok&&x.category==='ETF'&&candidateTier(x)==='buy'))[0];const scalp=(data.scalp_candidates||[])[0];const picks=[];if(individual)picks.push({lane:'개별주',item:individual,target:individual.target1_krw,stop:individual.stop1_krw});if(etf)picks.push({lane:'ETF',item:etf,target:etf.target1_krw,stop:etf.stop1_krw});if(scalp){const x=current.get(`${scalp.category||'KR'}:${scalp.code}`)||current.get(`KR:${scalp.code}`)||current.get(`US:${scalp.code}`);if(x)picks.push({lane:scalp.trade_class||'단기트레이딩',item:x,target:scalp.target_krw,stop:scalp.stop_krw,scalp})}
 const day=localDayKey(nowIso);picks.filter(p=>immediateAllowed(p.item)).forEach(p=>{const x=p.item,id=`${day}|${p.lane}|${resultKey(x)}`;if(history.some(r=>r.id===id))return;history.unshift({id,lane:p.lane,result_key:resultKey(x),market:normalizeMarket(x.market||x.category),code:x.code,name:x.name,created_at:nowIso,recommend_price:Number(x.price_krw||0),suggested_entry:Number(p.scalp?.entry_krw||x.entry_krw||0),target:Number(p.target||0),stop:Number(p.stop||0),opportunity_score:Number(x.opportunity_score||0),estimated_win_rate:Number(x.estimated_win_rate||50),validation_score:Number(x.backtest?.validation_score||0),reliability_factor:Number(x.backtest?.reliability_factor||0.5),market_regime:x.market_regime||'UNKNOWN',data_quality:Number(x.data_quality?.score||x.data_quality_score||0),tech:p.scalp?.tech||x.tech||'',current_return:0,observed_max_return:0,observed_min_return:0,d1_return:null,d3_return:null,d5_return:null,d10_return:null,d20_return:null,status:'진행중'})});
 const cutoff=Date.now()-120*864e5;const kept=history.filter(r=>new Date(r.created_at).getTime()>=cutoff).slice(0,200);saveJson(HISTORY_KEY,kept)}
function perfCell(v){if(v===null||v===undefined)return'-';const n=Number(v);return `${n>=0?'+':''}${n.toFixed(1)}%`}
function renderPerformance(){const box=$('performanceCards'),sum=$('performanceSummary'),history=loadJson(HISTORY_KEY,[]);box.innerHTML='';if(!history.length){sum.textContent='아직 누적된 추천 기록이 없습니다. 오늘 추천부터 이 기기에 자동 저장됩니다.';return}const d3=history.filter(x=>x.d3_return!==null&&x.d3_return!==undefined);if(d3.length){const plus=d3.filter(x=>Number(x.d3_return)>0).length,avg=d3.reduce((a,x)=>a+Number(x.d3_return||0),0)/d3.length;sum.innerHTML=`D+3 관찰 <b>${d3.length}건</b> · 플러스 비율 <b>${Math.round(plus/d3.length*100)}%</b> · 평균 <b>${perfCell(avg)}</b> <span>※ 과거 관찰값, 미래 승률 아님</span>`}else sum.textContent=`추천 기록 ${history.length}건 · D+3 데이터가 쌓이는 중입니다.`;history.slice(0,10).forEach(r=>{const d=document.createElement('div');d.className='performance-item';d.innerHTML=`<div class="perf-head"><span>${escapeText(r.lane)}</span><b>${escapeText(r.name)}</b><em>${escapeText(r.status||'진행중')}</em></div><small>${dateLabel(r.created_at)} · 추천가 ${fmt(r.recommend_price)}원 · 진입참고 ${fmt(r.suggested_entry)}원</small><div class="perf-grid"><span>D+1<b>${perfCell(r.d1_return)}</b></span><span>D+3<b>${perfCell(r.d3_return)}</b></span><span>D+5<b>${perfCell(r.d5_return)}</b></span><span>D+10<b>${perfCell(r.d10_return)}</b></span><span>D+20<b>${perfCell(r.d20_return)}</b></span><span>현재<b>${perfCell(r.current_return)}</b></span></div><div class="perf-range">관찰 최고 ${perfCell(r.observed_max_return)} · 관찰 최저 ${perfCell(r.observed_min_return)}</div>`;box.appendChild(d)})}
function feedbackStats(rows){
 const done=rows.filter(r=>r.d5_return!==null&&r.d5_return!==undefined);if(!done.length)return null;
 const wins=done.filter(r=>Number(r.d5_return)>0).length,avg=done.reduce((a,r)=>a+Number(r.d5_return||0),0)/done.length;
 const brier=done.reduce((a,r)=>{const p=Math.max(0,Math.min(1,Number(r.estimated_win_rate||50)/100)),y=Number(r.d5_return)>0?1:0;return a+(p-y)*(p-y)},0)/done.length;
 const group=(key)=>{const m={};done.forEach(r=>{const k=String(r[key]||'UNKNOWN');(m[k]??=[]).push(Number(r.d5_return||0))});return Object.entries(m).map(([k,v])=>({k,n:v.length,avg:v.reduce((a,b)=>a+b,0)/v.length,win:v.filter(x=>x>0).length/v.length*100})).sort((a,b)=>b.n-a.n)};
 return{n:done.length,win:wins/done.length*100,avg,brier,byTech:group('tech'),byRegime:group('market_regime'),byLane:group('lane')};
}
function renderFeedback(){const box=$('feedbackEngine'),history=loadJson(HISTORY_KEY,[]),st=feedbackStats(history);if(!box)return;if(!st){box.innerHTML='<div class="quality-empty">D+5 완료 기록이 쌓이면 전략·시장국면별 자동 피드백을 표시합니다.</div>';return}const fmtGroup=(title,arr)=>`<div class="feedback-group"><b>${title}</b>${arr.slice(0,5).map(x=>`<span>${escapeText(x.k)} · ${x.n}건 · 승 ${x.win.toFixed(0)}% · 평균 ${perfCell(x.avg)}</span>`).join('')}</div>`;let calibration=st.brier<=.20?'양호':st.brier<=.25?'보통':'주의';const done=history.filter(r=>r.d5_return!==null&&r.d5_return!==undefined),recent=done.slice(0,20),base=done.slice(20);let drift='표본부족',driftClass='';if(recent.length>=10&&base.length>=10){const rw=recent.filter(r=>Number(r.d5_return)>0).length/recent.length*100,bw=base.filter(r=>Number(r.d5_return)>0).length/base.length*100,delta=rw-bw;drift=delta<=-15?'위험':delta<=-8?'주의':'정상';driftClass=` · 최근-기준 ${delta>=0?'+':''}${delta.toFixed(0)}%p`;}box.innerHTML=`<div class="feedback-kpis"><span>모델 드리프트<b>${drift}${driftClass}</b></span><span>D+5 표본<b>${st.n}건</b></span><span>실현 플러스 비율<b>${st.win.toFixed(0)}%</b></span><span>평균수익<b>${perfCell(st.avg)}</b></span><span>확률오차(Brier)<b>${st.brier.toFixed(3)} · ${calibration}</b></span></div>${fmtGroup('전략별',st.byTech)}${fmtGroup('시장국면별',st.byRegime)}${fmtGroup('추천유형별',st.byLane)}<p class="quality-note">Brier는 0에 가까울수록 저장 당시 추정확률과 실제 D+5 방향이 잘 맞았다는 뜻입니다. 표본 20건 미만은 결론보다 관찰용으로 보세요.</p>`}
function saveSettings(){const d={};fields.forEach(k=>d[k]=$(k).value);localStorage.setItem(SETTINGS_KEY,JSON.stringify(d));try{const id=String($('accountId')?.value||'').trim().toLowerCase();if(id)localStorage.setItem(ACCOUNT_ID_KEY,id)}catch(e){}}
function saveAccountSecret(){try{sessionStorage.setItem(ACCOUNT_SECRET_KEY,String($('accountPassword')?.value||''))}catch(e){}}
function loadSettings(){try{let raw=localStorage.getItem(SETTINGS_KEY);if(!raw){raw=localStorage.getItem('v78.6.3-settings')||localStorage.getItem('v78.6.2-settings')||localStorage.getItem('v78.6.1-settings')||localStorage.getItem('v78.6.0-settings')||localStorage.getItem('v78.3.0-settings')||localStorage.getItem('v78.1.0-settings')||localStorage.getItem('v70.14.2-settings')||localStorage.getItem('v70.14.1-settings');if(raw){const old=JSON.parse(raw||'{}');delete old.accountPassword;localStorage.setItem(SETTINGS_KEY,JSON.stringify(old));raw=JSON.stringify(old)}}const d=JSON.parse(raw||'{}');fields.forEach(k=>{if(d[k]!==undefined)$(k).value=d[k]});if($('accountId')&&!String($('accountId').value||'').trim())$('accountId').value=localStorage.getItem(ACCOUNT_ID_KEY)||'';const pw=sessionStorage.getItem(ACCOUNT_SECRET_KEY)||'';if($('accountPassword'))$('accountPassword').value=pw;for(const k of ['v78.6.3-settings','v78.6.2-settings','v78.6.1-settings','v78.6.0-settings','v78.5.0-settings']){try{const od=JSON.parse(localStorage.getItem(k)||'null');if(od&&od.accountPassword!==undefined){delete od.accountPassword;localStorage.setItem(k,JSON.stringify(od))}}catch(_){}}}catch(e){}}
fields.forEach(k=>$(k).addEventListener('change',saveSettings));
function settingsPayload(){return{budget:Number($('budget').value||0),trade_budget:Number($('tradeBudget').value||0),long_budget:Number($('longBudget').value||0),saving_goal_krw:Number($('savingGoal').value||1000000),monthly_saving_krw:Number($('monthlySaving').value||100000),current_saving_krw:Number($('currentSaving').value||0),risk_pct:Number($('riskPct').value||0),stop_pct:Number($('stopPct').value||0),min_rrr:Number($('minRrr').value||1.5),trust_mode:$('trustMode').value,mode:$('mode').value,top_n:Number($('topN').value||60),held:$('held').value.trim()}}
function updateMoneyNote(){const budget=Number($('budget').value||0),trade=Number($('tradeBudget').value||0),risk=Number($('riskPct').value||0);$('moneyNote').textContent=`현재 설정: 전체 ${fmt(budget)}원 · 종목당 ${fmt(trade)}원 · 최대 허용손실 ${fmt(budget*risk/100)}원`}
function beginnerVerdict(item){
 if(!item||!item.ok)return{level:'red',text:'🔴 데이터 확인 필요',why:['데이터를 정상적으로 받지 못했습니다.']};
 if(item.hard_block)return{level:'red',text:'🔴 안전장치: 신규매수 금지',why:(item.risk_flags&&item.risk_flags.length?item.risk_flags:['데이터 신뢰도 또는 극저유동성 기준 미충족'])};
 const g=String(item.grade||'C'),q=Number(item.qty||0),r=Number(item.rrr||0),m=Number(item.momentum||0),o=Number(item.opportunity_score||0),rank=Number(item.buyable_rank||0),sess=sessionForItem(item);
 const wait=Number(item.entry_krw||0)<Number(item.price_krw||0)*.995;
 if(item.opportunity_eligible&&q>0){
  const rankText=rank?` · 후보 ${rank}위`:'';
  const adaptive=item.adaptive_candidate?' · 강세장 적응형':'';
  if(!sess.open){const action=sess.state==='pre'?'⏰ 장전 관심 후보':'📅 다음 장 관심 후보';return{level:'green',text:`${action}${rankText}${adaptive}`,why:[`${sess.label} — 지금 즉시 매수 신호로 보지 마세요.`,`수익기회 ${o.toFixed(0)}점 · ${g}급 · 손익비 1:${r.toFixed(2)}`,item.candidate_reason||`다음 정규장에 거래량·갭을 다시 확인한 뒤 ${fmt(item.entry_krw)}원 부근 판단`]};}
  if(item.adaptive_candidate)return{level:'green',text:`🟢 강세장 분할 후보${rankText}`,why:[item.candidate_reason||`시장 확산도 ${Number(item.market_breadth_score||0).toFixed(0)}점`,`손익비 1:${r.toFixed(2)} · 모멘텀 ${m.toFixed(0)}점`,`${q}주 이내 소액 분할 · 과열 시 추격 금지`]};
  if(wait)return{level:'green',text:`🟢 이 가격 오면 매수 후보${rankText}`,why:[`수익기회 ${o.toFixed(0)}점 · ${g}급`,`손익비 1:${r.toFixed(2)} · 모멘텀 ${m.toFixed(0)}점`,`${fmt(item.entry_krw)}원 부근에서 ${q}주 이내 분할`]};
  return{level:'green',text:`🔥 매수 가능 후보${rankText}`,why:[`수익기회 ${o.toFixed(0)}점 · ${g}급`,`손익비 1:${r.toFixed(2)} · 모멘텀 ${m.toFixed(0)}점`,`예산·허용손실 기준 ${q}주 이내`]};
 }
 if(item.opportunity_eligible&&item.allocation_wait)return{level:'yellow',text:'🟡 기준통과 · 계좌 위험한도 순번대기',why:[item.candidate_reason||`수익기회 ${o.toFixed(0)}점`,'종목 자체 기준은 통과했지만 현재 동시 신규진입 위험한도가 찼습니다.','기존 후보 종료·수량 감소 뒤 다시 배정합니다.']};
 if(item.near_buy_candidate)return{level:'yellow',text:sess.open?'🟡 강세장 진입 근접':closedActionText(item,'진입 근접'),why:[item.candidate_reason||`수익기회 ${o.toFixed(0)}점`,`시장 확산도 ${Number(item.market_breadth_score||0).toFixed(0)}점 · ${item.market_breadth_label||''}`,'한 단계 추가 확인 시 분할 후보로 승격될 수 있습니다.']};
 if(o>=62&&q>0)return{level:'yellow',text:sess.open?'🟡 공격형은 분할 관찰':closedActionText(item,'공격형 관찰'),why:[`수익기회 ${o.toFixed(0)}점`,`손익비 1:${r.toFixed(2)} · 모멘텀 ${m.toFixed(0)}점`,sess.open?'신호 한 가지 더 확인 후 소액 진입 검토':'다음 정규장 시초 갭·거래량 재확인']};
 if(o>=52)return{level:'yellow',text:sess.open?'🟡 관찰 후보':closedActionText(item,'관찰 후보'),why:[`수익기회 ${o.toFixed(0)}점 · 아직 진입조건 부족`,`손익비 1:${r.toFixed(2)} · 모멘텀 ${m.toFixed(0)}점`,'가격이나 거래량이 좋아지면 순위가 올라갑니다.']};
 return{level:'red',text:'🔴 현재는 후순위',why:[`수익기회 ${o.toFixed(0)}점`,`손익비 1:${r.toFixed(2)} · 모멘텀 ${m.toFixed(0)}점`,'지금은 더 강한 후보가 우선입니다.']};
}
function scoreItem(x){return Number(x.opportunity_score||0)*10+Number(x.rrr||0)*5+Number(x.momentum||0)+(x.opportunity_eligible?1000:0)-(x.hard_block?2000:0)}
function sortedDefault(items){return[...items].sort((a,b)=>scoreItem(b)-scoreItem(a))}
function sessionSorted(items){return sortedDefault(items).sort((a,b)=>Number(immediateAllowed(b))-Number(immediateAllowed(a))||scoreItem(b)-scoreItem(a))}
function candidateTier(x){
 if(!x||!x.ok||x.hard_block)return'blocked';
 if(x.opportunity_eligible&&Number(x.qty||0)>0)return'buy';
 if(x.opportunity_eligible&&x.allocation_wait)return'queue';
 if(x.near_buy_candidate)return'watch';
 if(Number(x.opportunity_score||0)>=55&&Number(x.rrr||0)>=1&&Number(x.qty_capacity||0)>0)return'watch';
 return'other';
}
