function signalClass(el,state){el.classList.remove('good','warn','bad');el.classList.add(state)}
function renderJudgeSix(tpl,item){
 const budget=tpl.querySelector('.j-budget'),rr=tpl.querySelector('.j-rrr'),mo=tpl.querySelector('.j-mom'),vo=tpl.querySelector('.j-vol'),tr=tpl.querySelector('.j-trend'),cf=tpl.querySelector('.j-conf');
 budget.textContent=item.qty>0?`${item.qty}주 가능`:'진입 보류';signalClass(budget,item.qty>=4?'good':item.qty>0?'warn':'bad');
 rr.textContent=`1:${Number(item.rrr||0).toFixed(2)}`;signalClass(rr,item.rrr>=1.5?'good':item.rrr>=1?'warn':'bad');
 mo.textContent=`${Number(item.momentum||0).toFixed(0)}점`;signalClass(mo,item.momentum>=70?'good':item.momentum>=50?'warn':'bad');
 vo.textContent=`${Number(item.rvol||0).toFixed(2)}배`;signalClass(vo,item.rvol>=1.5?'good':item.rvol>=1?'warn':'bad');
 const trend=(item.price_krw>=item.ma20_krw&&item.macd_bull)?'상승 우위':(item.price_krw>=item.ma20_krw?'20일선 위':'추세 약화');tr.textContent=trend;signalClass(tr,trend==='상승 우위'?'good':trend==='20일선 위'?'warn':'bad');
 cf.textContent=`${Number(item.opportunity_score||0).toFixed(0)}점`;signalClass(cf,item.opportunity_score>=72?'good':item.opportunity_score>=52?'warn':'bad');
}
