function restoreAutoReport(){let p=loadJson(AUTO_REPORT_KEY,null);if(!p){for(const k of LEGACY_AUTO_REPORT_KEYS){p=loadJson(k,null);if(p)break}}if(p&&Array.isArray(p.rows)&&p.rows.length){renderAutoReportPack(p);$('autoReportStatus').textContent=`저장된 자동 리포트 ${p.rows.length}개 표시 · ${dateLabel(p.generated_at)} · 최신 분석 후 자동 갱신됩니다.`;return true}return false}
let autoReportQueued=null;
async function reportBuildRow(rec){
 const item=await reportAnalyzeCandidate(rec),extra=await reportExtraBundle(item),fund=extra.fund||{},news=extra.news||{},assessment=reportAssessment(item,fund,news,rec.meta),verdict=reportVerdict(item,assessment),pc=reportProsCons(item,fund,news,assessment),peer=reportPeerContext(item),sections=report15Sections(item,fund,news,rec.meta,peer,assessment);let oneLine=`${verdict.label} · ${verdict.action}.`;if(rec.sources.includes('급등주'))oneLine+=` 급등 탐색값은 매수근거가 아니며 당일 +${assessment.dayPct.toFixed(1)}%를 반영해 추격 위험을 별도 감점했습니다.`;if(assessment.confidence<50)oneLine+=` 근거 완성도 ${assessment.confidence}%로 낮아 보수적으로 해석해야 합니다.`;if(item.hard_block)oneLine+=' 하드 리스크 조건이 있어 신규 진입을 우선 보류합니다.';return{item,fund,news,score:assessment.score,assessment,verdict,pc,peer,sections,sources:rec.sources,meta:rec.meta,providerErrors:extra.errors||[],oneLine}
}
async function generateAutoReport(opts={}){
 if(autoReportBusy){autoReportQueued={...(autoReportQueued||{}),...opts,skipEnsure:true};return null}autoReportBusy=true;const btn=$('autoReportBtn');if(btn){btn.disabled=true;btn.textContent='리포트 생성 중…'};$('autoReportStatus').textContent='급등주·V78 후보·관심주를 모으고 실적·뉴스·리스크 게이트를 자동 확인 중입니다.';
 try{if(!opts.skipEnsure&&$('reportIncludeRecommend')?.checked!==false)await ensureMainAnalysisForReport();await ensureSurgeRowsForReport();const limit=Math.max(4,Math.min(8,Number($('reportCount')?.value||6))),pool=reportCandidatePool(limit);if(!pool.length)throw new Error('리포트 후보가 없습니다. 포함 항목을 확인하세요.');
  const rows=[],failed=[];let next=0,done=0;const worker=async()=>{while(next<pool.length){const rec=pool[next++];try{rows.push(await reportBuildRow(rec))}catch(e){failed.push(rec.query);console.warn('auto report item failed',rec.query,e)}done++;$('autoReportStatus').textContent=`자동 리포트 ${done}/${pool.length} 완료 · 실적·뉴스·과열·진입거리 교차확인 중…`}};
  await Promise.all([worker(),worker()]);if(!rows.length)throw new Error(`후보 ${pool.length}개 분석이 모두 실패했습니다${failed.length?` (${failed.slice(0,3).join(', ')})`:''}.`);
  rows.sort((a,b)=>b.score-a.score||Number(b.assessment?.confidence||0)-Number(a.assessment?.confidence||0));const pack={schema:2,generated_at:new Date().toISOString(),rows};saveJson(AUTO_REPORT_KEY,pack);renderAutoReportPack(pack);$('autoReportStatus').textContent=`✅ 자동 리포트 ${rows.length}개 생성 완료 · 급등주/V78 후보/관심주 중복 제거 · 검토점수+근거완성도 분리${failed.length?` · 분석 실패 ${failed.length}개 제외`:''} · ${dateLabel(pack.generated_at)}`;return pack
 }catch(e){$('autoReportStatus').textContent=`자동 리포트 오류: ${e.message}`;return null}finally{autoReportBusy=false;if(btn){btn.disabled=false;btn.textContent='오늘 리포트 자동 생성'}if(autoReportQueued){const q=autoReportQueued;autoReportQueued=null;setTimeout(()=>generateAutoReport(q),150)}}
}
$('autoReportBtn')?.addEventListener('click',()=>generateAutoReport());['reportIncludeSurge','reportIncludeRecommend','reportIncludeWatch','reportCount'].forEach(id=>$(id)?.addEventListener('change',()=>generateAutoReport({skipEnsure:allResults.some(x=>x.ok)})));
if(!restoreAutoReport())$('autoReportList').innerHTML='<div class="quality-empty">최신 분석 후 자동 리포트가 생성됩니다.</div>';

